INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'Citizenship', 'Unit 2', 'Molarum Grade 10 — Citizenship Unit 2: Citizens in the Digital Technology Age', 'Source-grounded Molarum Grade 10 Citizenship questions for Unit 2: Citizens in the Digital Technology Age.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('a37f6a19-bd05-4d25-8e4d-f1131f6be5e1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which one of the following is not included under the principles of democratic system?', 'The existence of one-party system', 'The excerpt lists popular sovereignty, accountability and transparency, and universal suffrage as democratic principles and contrasts these with one-party systems, which are not democratic principles.', 0),('017dd4d2-1425-4304-86f4-1f1356a79674'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is listed as a key word for Unit 2?', 'Digital citizenship', 'The key words section of the unit explicitly lists ''Digital citizenship'' as a key word for Unit 2.', 1),('7cbdc389-89c5-4edd-8d7b-2596f3085db7'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'How many lessons are listed under Unit 2 in the introduction?', 'Four', 'The unit lists four lessons: Implications of digital technology on citizens; The ethics of using digital technology; Opportunities of digital technology for young citizens; and The impacts of unethical use of digital technology on young citizens.', 2),('38cfbe3d-9a8d-4d80-8f4f-adcda6ffc8a5'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is presented as a positive implication of digital technology on emotions?', 'Self-control', 'The excerpt lists self-control as a positive effect of digital technology on citizens'' emotions, while isolation, anonymity, and depression are described as negative implications.', 3),('110a45d4-5d96-47fc-84fb-c32250e271c1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which statement about excessive digital technology use is supported by the excerpt?', 'Excessive use typically leads to negative effects', 'The excerpt states that moderate use produces positive effects whereas excessive, obsessive, or addictive use typically leads to negative effects on emotions.', 4),('e9530dcb-1da0-4370-8e39-808774d0c9c6'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which example in the excerpt illustrates how digital technology fosters socialization?', 'Mobile phones enable people to stay closer to loved ones across distances', 'The excerpt explains that digital technologies allow people to stay closer to loved ones when physically far apart, which fosters socialization; other options are unsupported or contradicted by the text.', 5),('405c28e0-88ad-443e-85df-ac7fd6ce0077'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'According to the excerpt, which role can digital technology play in emotion regulation?', 'It gives access to health and wellness resources to build skills like mindfulness', 'The excerpt states that technology provides access to health and wellness resources and can teach skills such as gratitude, mindfulness, and emotion regulation.', 6),('a32337e0-078f-4960-8e31-4454a2357adb'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is described as a form of ''secondhand living''?', 'Creating imaginary identities and spending hours in virtual worlds', 'Secondhand living is described as people creating imaginary identities in virtual worlds and becoming preoccupied with virtual realities instead of firsthand life.', 7),('3daa3c5a-cb20-4193-8aeb-c20f1884f755'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which reason does the excerpt give for why websites and games encourage prolonged use?', 'They want users to interact so they can bring in advertising money', 'The excerpt explains that websites and games are designed to keep users interacting because this interaction brings in advertising revenue or encourages purchases, which can lead to addiction.', 8),('cd0d56d8-97c9-4a49-8e4d-c333bc6d6758'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is NOT listed as a positive implication of digital technology on social life in the excerpt?', 'Creating social alienation', 'Speedy communication, promoting economic growth, and improving health care are listed as positive implications, whereas social alienation is listed among negative social impacts.', 9),('e809d382-915c-4d5b-8a2b-b66c207cfd3e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'How has digitalization changed banking and finance according to the excerpt?', 'Online banking can be done via laptop, tablet, or phone and helps arrange transfers and payments', 'The excerpt states that online banking is performed via laptops, tablets, or phones and users can remotely check payments and arrange transfers and bill payments.', 10),('e362621b-1820-45dd-8091-e72a7ce5929e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which benefit of digital technology to health care is mentioned in the excerpt?', 'Patients can access diagnostic tools and keep track of appointments via handheld devices', 'The excerpt notes that patients have access to diagnostic tools and can use applications to manage appointments and medication reminders via handheld devices.', 11),('0fd755e4-778b-4b5d-8c09-9c7654a8f743'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which negative social effect does the excerpt link to lack of real-life contact?', 'Social alienation', 'The excerpt explains that increased reliance on digital devices for interaction can lead to social alienation due to reduced real-life contact.', 12),('86a75f1e-5b69-4555-8cca-46cd2cbdd527'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which example from the excerpt illustrates erosion of privacy?', 'Employers searching for people online and finding unflattering photographs', 'The excerpt gives the example that employers can search online and find unflattering photos or controversial opinions, demonstrating erosion of privacy.', 13),('3ffcbf5a-ef8a-4c5c-824c-0f72c52c4210'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'What cause of job insecurity is described in the excerpt?', 'Computers replacing human tasks and remote work enabling undercutting of wages', 'The excerpt states that computers replace many tasks and remote work allows workers in low-wage economies to undercut others, causing job insecurity.', 14),('04d74193-2c89-471c-8c36-18043aa93efa'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which risk of data insecurity is mentioned in the excerpt?', 'A single breach can expose vast amounts of private information', 'The excerpt warns that huge amounts of private information are stored digitally and a single breach can put this data into the hands of criminals or other harmful entities.', 15),('642bd23a-32fe-4f68-8193-f9f6a16ac362'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'How does the excerpt describe the internet''s role in crime and terrorism?', 'A fertile ground for malevolent forces to operate internationally and on vast scales', 'The excerpt states the internet is fertile ground for malevolent forces such as terrorists and drug dealers to operate internationally and at scale.', 16),('90d7b6ce-64c5-4aaf-8ba3-42f8c0714347'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which physical health issue is linked to prolonged use of digital devices in the excerpt?', 'Eyestrain and blurred vision', 'The excerpt notes that prolonged attention to digital devices can cause digital eyestrain, with symptoms like blurred vision and dry eyes.', 17),('a9bbae25-d0c4-48c0-8f8f-7a121d7c5b91'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which of the following is listed as an ethical code/principle in using digital technology?', 'Etiquette', 'The excerpt lists etiquette as one of the ethical codes guiding appropriate behaviour when using digital technology.', 18),('7b04dec1-ceef-4bc2-8a58-9765ebe390f6'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'multiple_choice', 'Which behaviour is given as an example of inappropriate responsibility in the excerpt?', 'Students copy materials from the internet without giving credit', 'The excerpt explicitly cites students copying internet materials for class projects without crediting the author as an example of inappropriate responsibility.', 19),('a368e950-9e1a-43f6-8444-0fdb434c9bce'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'The excerpt states that protecting one’s equipment is only a matter of personal responsibility and has no relevance to community safety.', 'False', 'The excerpt explains that protecting one’s equipment is both personal responsibility and necessary for protecting the community, so the statement is false.', 20),('4d78cd3d-f77d-43e4-8b59-ea8b8d0937e8'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'According to the excerpt, telling your email or social media passwords to others is an example of inappropriate confidentiality.', 'True', 'The excerpt lists sharing email, Facebook, and other passwords as an example of inappropriate confidentiality, so the statement is true.', 21),('6c489d06-5e00-48ae-8d3a-b3c0e3eb78ac'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'The excerpt claims there is an agency that guarantees truth and accuracy of all internet information.', 'False', 'The excerpt states there is no agency monitoring truth or accuracy of information on the internet, so the claim is false.', 22),('d0621c52-718f-4949-8c0a-b674f855431e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'true_false', 'The excerpt asserts that developing digital citizenship for children and young people has been a priority in many countries.', 'True', 'The excerpt states that developing digital citizenship and ensuring children are active and respectful online users has been a priority in countries around the world.', 23),('6ecd7ec7-2627-4458-8a6c-1d797425ba6e'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Briefly explain how digital technology provides information access for young citizens as described in the excerpt.', 'The excerpt explains digital technology gives open access to information about local and global events, enabling young citizens to engage collaboratively and be part of world conversations.', 'The unit states that digital technology is a window to information about one’s country and the world, which helps young people participate and collaborate globally.', 24),('d226440b-30d5-4c26-8e56-29eae14edbd1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'What learning opportunities does the excerpt say digital technology offers?', 'It allows access to a huge portion of the world’s knowledge, virtual delivery of lessons and courses, direct learning from sources, short-term trainings, and skill development via videos and audios.', 'The excerpt lists virtual lessons, access to global knowledge, short trainings, and multimedia resources as ways digital technology advances learning.', 25),('ebdd2f1b-f23f-49d9-8aaf-6b69c75e6993'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How does the excerpt describe versatile working opportunities created by digital technology for young people?', 'The excerpt notes increased connectivity allows remote work from home and easier searching and applying for online job opportunities, expanding work options for young people.', 'The unit explains that many jobs can be done remotely and digital tools enable young people to find and apply for work online, creating versatile work opportunities.', 26),('ace0e3cb-94df-4938-85ce-07e0e87634ef'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'According to the excerpt, why is digital technology fertile ground for innovation and creativity among the young?', 'Because access to information, connectivity, and digital learning exposes young people to new ideas and technologies that enable creativity and innovation.', 'The excerpt states that information access and connectivity provide enabling factors for exposure to new ideas, promoting creativity and innovation among young citizens.', 27),('428ce212-71f1-40be-8b29-dd79a2eb923a'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Define ''plagiarism'' as given in the excerpt.', 'Plagiarism is presenting the ideas, words, or other intellectual property of other persons as one’s own without credit.', 'The excerpt defines plagiarism as using someone else’s work or ideas and presenting them as your own, which is an unethical academic practice.', 28),('74e973a5-bc55-478a-8557-075418b08a19'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'What is digital media piracy according to the excerpt?', 'Digital media piracy is the illegal circulation and distribution of music, movies, books and other copyrighted content through digital technologies without permission.', 'The excerpt describes piracy as unauthorized distribution of copyrighted material online, violating property rights and harming production industries.', 29),('0f6afd17-f7c5-4d8d-87ce-35a5a3c63ec4'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'What negative effect does the excerpt associate with sharing suggestive videos among young people?', 'The excerpt links sharing suggestive videos to early sexual experiences, addiction to what is watched, relationship separation, and wider problems in education and family life.', 'The text explains that sharing and watching suggestive videos can lead to early sexual behaviour, addiction, and negative impacts on education and family relationships.', 30),('34e8013b-9d02-4bb6-8d29-8624b5466278'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Explain what an ''ethical dilemma'' means as defined in the glossary of the excerpt.', 'An ethical dilemma is a decision-making problem with two possible options where neither is absolutely acceptable from an ethical perspective.', 'The glossary defines ethical dilemma as facing two options, neither of which is fully acceptable ethically, illustrating moral conflict.', 31),('279e538c-9694-4aee-8391-ab8523ce617d'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many lessons are numbered under Unit 2 in the unit introduction?', '4', 'The unit introduction lists four lessons numbered 1 to 4 under Unit 2.', 32),('356e0128-bcdf-4eed-881c-3a72530740bc'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many key words are listed at the start of Unit 2?', '4', 'The key words section lists Digital citizenship, Digital ethics, Digital technology, and Ethical dilemma, a total of four key words.', 33),('48f842cc-a657-4e3a-857f-9c736815f5c1'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many ethical codes/principles (named headings) are described in Lesson 2.2 (Etiquette through Accuracy/trustworthiness)?', '6', 'Lesson 2.2 lists six ethical codes by heading: Etiquette, Responsibility, Safety, Security, Confidentiality, and Accuracy/trustworthiness.', 34),('cf15a80c-946d-4b1c-8585-44bcbb6aa4b8'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'Count the number of positive implications of digital technology on citizens'' emotions that are listed by heading (from Self-control to Increased emotional satisfaction).', '7', 'The excerpt lists seven positive emotional implications by heading: Self-control; Fostering socialization; Maintaining emotional balance; Supporting happiness and wellbeing; Regulating emotions; Providing a sense of security; Increased emotional satisfaction.', 35),('a3b7815d-2009-497f-8d14-921385a22476'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many negative implications of digital technology on the social life are explicitly listed (Social alienation through Effects on physical health)?', '6', 'The excerpt discusses six negative social impacts: Social alienation, Eroding privacy, Job insecurity, Data insecurity, Aggravate crime and terrorism, and Effects on physical health.', 36),('fcb1d3ed-8182-4de4-8ee7-6417fed7b1b8'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many specific opportunities of digital technology for young citizens are listed in Lesson 2.3 (Information access through Innovation and creative opportunities)?', '5', 'Lesson 2.3 lists five opportunities: Information access; Social connectivity; Learning opportunities; Versatile working opportunities; and Innovation and creative opportunities.', 37),('3f5ab752-1d7f-4fef-8451-474a7c53ef8a'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many specific impacts of unethical use of digital technology on young citizens are listed at the start of Lesson 2.4 (Academic dishonesty through Identity theft and Unfriendly and revenge sex)?', '4', 'The excerpt lists four impacts under that heading: Academic dishonesty, Digital media piracy, Identity theft, and Unfriendly and revenge sex.', 38),('5b2fcad4-ff9f-485d-84f7-8ca62760f656'::uuid, '08e2efe3-ea9a-403a-8115-bc71cdf2cde5'::uuid, 'fill_blank', 'How many glossary entries are shown at the end of the excerpt (from Cyber security to Plagiarism)?', '11', 'The glossary provides eleven entries starting with Cyber security and ending with Plagiarism as listed in the excerpt.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
